def find_occurrences(g, out):
 h,w=len(out),len(out[0]); a=np.array(g); o=np.array(out)
 res=[]
 # exact rectangles in normal orientation
 for r in range(31-h):
  for c in range(31-w):
   if np.array_equal(a[r:r+h,c:c+w],o): res.append((r,c,'exact'))
 # transformations only applicable matching dimensions
 for r in range(31-h):
  for c in range(31-w):
   p=a[r:r+h,c:c+w]
   opts=[('ud',p[::-1,:]),('lr',p[:,::-1]),('rot180',p[::-1,::-1])]
   for name,q in opts:
    if np.array_equal(q,o):res.append((r,c,name))
 return res
for i,(g,o) in enumerate(pairs,1):
 print('demo',i,'mask dims',len(o),len(o[0]),'occurrences',find_occurrences(g,o))

def bbox8(g):
 a=np.array(g); pos=np.argwhere(a==8); return tuple(pos.min(0)),tuple(pos.max(0))
for di,(g,o) in enumerate(pairs,1):
 (r0,c0),(r1,c1)=bbox8(g)
 out=np.array(o); print('demo',di,'bbox',(r0,c0,r1,c1))
 for axis_sum in range(27,34):
  rr=[axis_sum-r for r in range(r0,r1+1)]
  cc=[axis_sum-c for c in range(c0,c1+1)]
  # reflecting rows if row axis, cols if col axis
  if min(cc)>=0 and max(cc)<30:
   cand=np.array(g)[r0:r1+1,:][:,cc]
